 function zoneUI(t){return '<h3>禁柱区</h3><p>选择“禁柱区＋涂选”，拖出矩形。内部不自动布柱；边界和角点允许放柱，不会自动沿边补柱。已有手动柱保留并提示冲突。</p>'+table(['删除','X₁ m','Y₁ m','X₂ m','Y₂ m'],(t.noColumnZones||[]).map((r,i)=>[button('×','delete-no-column',i),...['x0','y0','x1','y1'].map(k=>input(r[k],'no-column-zone',i,k))]))+'<div class="row">'+['x0','y0','x1','y1'].map(k=>'<label class="field">'+k+' m<input id="zone-'+k+'" type="number"></label>').join('')+'</div>'+button('加入禁柱区','add-no-column');}
 function gridChange(a){const d=a.dataset,action=d.action;if(action==='cg-x'||action==='cg-y'){const axis=action.at(-1);transact(()=>{const ar=p.types[key].columnGrid[axis];ar[+d.i]=Number(a.value);ar.sort((a,b)=>a-b);});gridPreview=null;return true;}if(action==='no-column-zone'){transact(()=>p.types[key].noColumnZones[+d.i][d.f]=a.value===''?null:Number(a.value));return true;}if(action==='legacy-column-min'){transact(()=>p.types[key].minColumnSpacing=a.value===''?0:Number(a.value));return true;}return false;}
 function gridAction(action,b){if(action==='draw-column-grid'){sbAreaDrawing=false;zoneDrag=null;tab='columns';mode='plan';selectOnly=false;showColumnGrid=true;$('show-column-grid').checked=true;start=selected=null;refresh();return true;}const t=p.types[key],i=+b.dataset.i,number=id=>{const v=$(id).value;if(!v.trim())throw Error('请填写坐标／间距');const n=Number(v);if(!Number.isFinite(n))throw Error('请填写有效数字');return n;};try{
  if(action==='preview-column-grid'){gridPreview={key,base:JSON.stringify(Engine.axisData(p,key)),grid:Engine.columnGridDraft(p,key,number('cg-x'),number('cg-y'))};showColumnGrid=true;refresh();return true;}
  if(action==='apply-column-grid'){if(!gridPreview||gridPreview.key!==key||gridPreview.base!==JSON.stringify(Engine.axisData(p,key)))throw Error('请先预览当前柱轴线');transact(()=>t.columnGrid=Engine.clone(gridPreview.grid));gridPreview=null;refresh();return true;}
  if(action==='clear-column-grid'){transact(()=>delete t.columnGrid);gridPreview=null;refresh();return true;}
  if(action?.startsWith('remove-cg-')){transact(()=>t.columnGrid[action.at(-1)].splice(i,1));gridPreview=null;return true;}
  if(action?.startsWith('add-cg-')){const d=action.at(-1),v=number('cg-add-'+d);transact(()=>{t.columnGrid[d].push(v);t.columnGrid[d].sort((a,b)=>a-b);});gridPreview=null;return true;}
  if(action==='delete-no-column'){transact(()=>{t.noColumnZones.splice(i,1);selected=null;});return true;}
  if(action==='add-no-column'){const r=Object.fromEntries(['x0','y0','x1','y1'].map(k=>[k,number('zone-'+k)]));transact(()=>(t.noColumnZones??=[]).push(r));return true;}
  if(action==='delete-auto-column'){transact(()=>Engine.removeMember(p,key,{kind:'COL',id:b.dataset.i}));return true;}
  if(action==='pure-auto'){if(!confirm('清除当前 Framing 的手动补柱、删柱、手动柱位置和自动柱尺寸／Transfer 标记，恢复纯自动布柱？可撤销。'))return true;transact(()=>{t.columns=t.columns.filter(c=>!c.autoAdded);t.suppressedColumns=[];t.columnSizes=[];t.transferColumns=[];delete t.columnPlacements;delete t.columnAxisPositions;delete t.alignmentMinSpacing;});return true;}
  if(action==='addcolumn'){const x=number('col-add-x'),y=number('col-add-y');transact(()=>Engine.addColumn(p,key,x,y));return true;}
 }catch(e){toast(e.message);return true;}return false;}


 let groupDraft=null,groupDirty=false,groupTotal=1;
 function draftGroups(){if(!groupDraft||!groupDirty){let from=1;groupTotal=p.total;groupDraft=p.groups.map(g=>{const start=from;from=(g.end==='顶层'?p.total:g.end)+1;return {...g,start};});}return groupDraft;}
 function applyGroups(){if(!groupDirty)return true;try{if(!Number.isInteger(groupTotal)||groupTotal<1||groupTotal>500)throw Error('总层数须为 1–500 的整数');if(!groupDraft.length)throw Error('至少保留一组');const rows=Engine.clone(groupDraft).sort((a,b)=>a.start-b.start);let expected=1;for(const g of rows){const end=g.end==='顶层'?groupTotal:g.end;if(!Number.isInteger(g.start)||g.start<1||!Number.isInteger(end)||end<g.start||end>groupTotal)throw Error('请填写有效起始层及结束层（1–'+groupTotal+'）');if(g.start!==expected)throw Error(g.start<expected?'楼层范围重叠，请检查起始层及结束层':'漏填第 '+expected+' 层，请补齐楼层范围');expected=end+1;}if(expected!==groupTotal+1)throw Error('楼层分组须覆盖至第 '+groupTotal+' 层');const ok=transact(()=>{p.total=groupTotal;if(p.elevationLevels?.sequenceStart)FloorLevels.setSequence(p,p.elevationLevels.sequenceStart);if(p.elevationLevels?.names)for(const n of Object.keys(p.elevationLevels.names))if(+n>p.total)delete p.elevationLevels.names[n];p.groups=rows.map(({start,...g})=>({...g,sh:Engine.structuralHeight(g)}));LocalHeights96.syncGroups(p);});if(ok){groupDirty=false;groupDraft=null;key=result.floors[floor-1].type;refresh();toast('楼层分组已应用，可撤销');}return ok;}catch(e){toast(e.message);return false;}}

 let elevationFrom=1,elevationTo=null,elevationX='all',elevationY='all',elevationLabels=false;
