 function elevationLimits(){const hi=elevationTo===null?p.total:Math.max(1,Math.min(p.total,elevationTo)),lo=Math.max(1,Math.min(hi,elevationFrom));return {lo,hi};}
 function elevationOptions(d){const map=new Map();for(const type of new Set(result.floors.map(f=>f.type))){for(const a of Engine.axes(p,d,type)){const k=String(a.v);if(!map.has(k))map.set(k,{v:a.v,names:new Set()});map.get(k).names.add(a.id);}for(const a of Engine.columnAxes(p,d,type)){const k=String(a.v);if(!map.has(k))map.set(k,{v:a.v,names:new Set(['柱轴线'])});}}return [...map.entries()].sort((a,b)=>a[1].v-b[1].v).map(([k,a])=>({value:k,label:[...a.names].join('/')+' · '+a.v.toFixed(3)+' m'}));}
 let overallFace='B',overallShowReport=false;
