 function geometryChange(k,v){if(['breadth','depth','baseBreadth','baseDepth'].includes(k)){toast('B、D 由建筑范围自动读取');return true;}if(k==='basement'&&FloorLevels.managed(p)){toast('Basement 已按楼层名称自动识别，请在楼层设置修改');return true;}if(k!=='height')return false;transact(()=>{OverallGeometry.setRoof(p,v);p.overall??={version:1,faces:{}};for(const face of ['B','D']){p.overall.faces[face]??={input:Object.assign(Overall.normalize(null,face),{leftQ:null,rightQ:null})};p.overall.faces[face].input.height=v;delete p.overall.faces[face].committed;delete p.overall.faces[face].attempt;}});return true;}

