 function pointEvent(e){const r=$('canvas').getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top];}
 function setSlabDirections119(value){showSlabDirections119=!!value;try{localStorage.setItem('framing-slab-directions119',String(showSlabDirections119));}catch{}for(const id of ['show-slab-directions119','bl116-show-directions']){const el=$(id);if(el)el.checked=showSlabDirections119;}schedule();}
 function gridPoint(q){let best,dist=Infinity;for(const x of (tab==='columns'?Engine.columnAxes(p,'x',key):Engine.axes(p,'x',key)))for(const y of (tab==='columns'?Engine.columnAxes(p,'y',key):Engine.axes(p,'y',key))){const d=Math.hypot(q[0]-x.v,q[1]-y.v)*plot.scale;if(d<dist){dist=d;best={...(x.id.startsWith('@cg:')?{}:{ax:x.id,ay:y.id}),x:x.v,y:y.v};}}if(dist<15)return best;if(tab!=='columns')return null;
  // Prefer intersections, otherwise project onto the nearest column axis.
  const xs=Engine.columnAxes(p,'x',key),ys=Engine.columnAxes(p,'y',key),candidates=[];
  for(const x of xs)if(q[1]>=ys[0].v&&q[1]<=ys.at(-1).v)candidates.push({x:x.v,y:+q[1].toFixed(3),distance:Math.abs(q[0]-x.v)*plot.scale});
  for(const y of ys)if(q[0]>=xs[0].v&&q[0]<=xs.at(-1).v)candidates.push({x:+q[0].toFixed(3),y:y.v,distance:Math.abs(q[1]-y.v)*plot.scale});
  const nearest=candidates.sort((a,b)=>a.distance-b.distance)[0];return nearest?.distance<10?{x:nearest.x,y:nearest.y}:null;}
 function columnPoint(q){
  const m=Engine.floorModel(result,floor,key),points=m.beams.filter(b=>visible[b.kind]!==false).map(b=>({x:(b.a[0]+b.z[0])/2,y:(b.a[1]+b.z[1])/2}));
  const nearest=points.map(g=>({...g,d:Math.hypot(g.x-q[0],g.y-q[1])*plot.scale})).filter(g=>g.d<15).sort((a,b)=>a.d-b.d)[0];
  return nearest||gridPoint(q);
 }
 function beamPoint(q){
  const m=Engine.floorModel(result,floor,key),candidates=[],limit=15/plot.scale,near=(a,b)=>Math.abs(a-b)<1e-6;
  const add=g=>{if(!g)return;if(start&&!near(g.x,start[0])&&!near(g.y,start[1]))return;const d=Math.hypot(g.x-q[0],g.y-q[1]);if(d<=limit)candidates.push({...g,d});};
  for(const c of m.columns)for(const v of FloorColumns101.snap(c,start))add({x:v[0],y:v[1]});add(gridPoint(q));
  for(const b of [...m.beams,...m.walls])for(const a of [b.a,b.z,b.rawA,b.rawZ,[(b.a[0]+b.z[0])/2,(b.a[1]+b.z[1])/2]])add({x:a[0],y:a[1]});
  candidates.sort((a,b)=>a.d-b.d);if(candidates.length)return candidates[0];
  for(const b of [...m.beams,...m.walls]){
   const a=b.a,z=b.z,h=near(a[1],z[1]),lo=Math.min(a[h?0:1],z[h?0:1]),hi=Math.max(a[h?0:1],z[h?0:1]);
   let v=start&&!near(start[h?1:0],a[h?1:0])?start[h?0:1]:Math.max(lo,Math.min(hi,q[h?0:1]));
   if(v<lo-1e-6||v>hi+1e-6)continue;
   add(h?{x:v,y:a[1]}:{x:a[0],y:v});
  }
  candidates.sort((a,b)=>a.d-b.d);return candidates[0]||null;
 }
 function tileAt(q){return Engine.floorModel(result,floor,key).ts.find(t=>q[0]>=t.x0&&q[0]<t.x1&&q[1]>=t.y0&&q[1]<t.y1);}
